message.content:
{
  "description": "The creature is a large, powerfully built quadrupedal felid shown in right-facing side view with its head turned slightly toward the viewer. It has a robust, muscular body covered in dense, tawny golden-brown fur that is lighter cream-white on the chin, chest, belly and inner legs, with a shaggy ruff of longer fur around the neck and chest. The head is broad and cat-like with a short muzzle, the limbs are thick and sturdy ending in large paws, and a short tail extends from the rear. Faint dark striping is visible over much of the body, most distinctly on the lower legs and hindquarters. The overall impression is of a lion-like and tiger-like cat standing on a plain light background with a soft shadow beneath its feet.",
  "parts": [
    {
      "part": "head",
      "looks_like": "large broad felid head at the front of the body, turned three-quarters toward the viewer, with a pinkish-brown nose, white fur on the muzzle, chin and around the eyes, amber-brown eyes with white tear-like markings below, short white whiskers on the muzzle, and a slightly open mouth showing dark lips",
      "where": "at the anterior end of the body, atop the neck and chest ruff"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, fur-covered ears with dark black-brown patches on the backs and pale inner fur, tufted at the tips",
      "where": "on top of the head, one on each side, set wide apart"
    },
    {
      "part": "mane",
      "looks_like": "a shaggy ruff of longer, slightly darker tawny fur with lighter cream on the underside, not a full lion mane but a thickened collar of hair",
      "where": "encircling the neck, extending down the throat, chest and along the underside of the neck"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, fur-covered legs with faint dark horizontal striping that becomes bolder and darker on the lower segments; the two forelegs are nearly vertical under the chest and the two hind legs are angled with visible hock joints",
      "where": "two forelegs under the front of the torso and two hind legs under the rear of the torso, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large, rounded paws with blunt toes, thick pads and short claws, covered in tawny fur with darker fur between the toes, the front paws larger than the hind paws",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, fur-covered tail with alternating light and dark rings and a solid dark blackish tip with a pale band just before the tip",
      "where": "extending from the rear of the body at the rump, hanging down behind the right hind leg and curving slightly outward"
    },
    {
      "part": "markings",
      "looks_like": "faint to moderate dark brown-black tiger-like vertical stripes and bars over the tawny base coat, most distinct as dark rings on the lower forelegs and hind legs and as broken stripes on the flanks, back, hindquarters and forehead, with a paler belly and chest",
      "where": "distributed over the entire body, head, legs and tail, densest on the legs, sides and back"
    }
  ],
  "attached_objects": [],
  "animals": [
    "lion",
    "tiger"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
